ALTER TABLE "drive_objects" DROP CONSTRAINT "drive_objects_framing_valid", ADD CONSTRAINT "drive_objects_framing_valid" CHECK ("chunk_size" > 0 and "chunk_count" >= 1 and octet_length("content_nonce") = 16 and (("content_suite" = 1 and "plaintext_size" >= 0 and "ciphertext_size" = "plaintext_size" + 16 * "chunk_count") or ("content_suite" in (2, 3) and "plaintext_size" is null and "ciphertext_size" >= 16 * "chunk_count")));